var update = flag.Bool("update", false, "rewrite testdata/whistle_fixture_go.json")

// fixture is the cross-side signed-request fixture. The Go one is generated
// here (go test -run TestGoFixture -update) and copied to the Android test
// resources; the Kotlin one is generated by the app's WhistleFixtureTest and
// copied here. Each side verifies the other's.
type fixture struct {
	Comment         string `json:"comment"`
	PublicKey       string `json:"public_key"` // SPKI, standard base64
	DeviceID        string `json:"device_id"`
	Method          string `json:"method"`
	Path            string `json:"path"`
	Host            string `json:"host"`
	TS              int64  `json:"ts"`
	Nonce           string `json:"nonce"`
	Body            string `json:"body"`
	BodySHA256      string `json:"body_sha256"`
	EmptyBodySHA256 string `json:"empty_body_sha256"`
	Canonical       string `json:"canonical"`
	Sig             string `json:"sig"`
	Authorization   string `json:"authorization"`
	Welcome         *struct {
		ServerID string `json:"server_id"`
		Nonce    string `json:"nonce"`
		Message  string `json:"message"`
		Sig      string `json:"sig"`
	} `json:"welcome,omitempty"`
}

func checkFixture(t *testing.T, f fixture) {
	t.Helper()
	pub, err := ParsePublicKey(f.PublicKey)
	if err != nil {
		t.Fatal(err)
	}
	if got := BodyHash([]byte(f.Body)); got != f.BodySHA256 {
		t.Errorf("body hash %s != %s", got, f.BodySHA256)
	}
	if got := BodyHash(nil); got != f.EmptyBodySHA256 {
		t.Errorf("empty body hash %s != %s", got, f.EmptyBodySHA256)
	}
	if got := Canonical(f.Method, f.Path, f.Host, f.TS, f.Nonce, []byte(f.Body)); got != f.Canonical {
		t.Errorf("canonical mismatch:\n%q\n%q", got, f.Canonical)
	}
	if !Verify(pub, f.Canonical, f.Sig) {
		t.Error("signature does not verify")
	}
	h, err := ParseHeader(f.Authorization)
	if err != nil || h.Device != f.DeviceID || h.TS != f.TS || h.Nonce != f.Nonce || h.Sig != f.Sig {
		t.Errorf("header %+v %v", h, err)
	}
	if f.Welcome != nil {
		if WelcomeMessage(f.Welcome.ServerID, f.Welcome.Nonce) != f.Welcome.Message {
			t.Error("welcome message mismatch")
		}
		if !Verify(pub, f.Welcome.Message, f.Welcome.Sig) {
			t.Error("welcome sig does not verify")
		}
	}
}

func readFixture(t *testing.T, name string) fixture {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatal(err)
	}
	var f fixture
	if err := json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	return f
}

func TestGoFixture(t *testing.T) {
	if *update {
		k, _ := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
		f := fixture{
			Comment:   "Generated by bridge/internal/devauth (go test -run TestGoFixture -update). Verified by the Android app's WhistleFixtureTest.",
			PublicKey: base64.StdEncoding.EncodeToString(SPKI(&k.PublicKey)),
			DeviceID:  "d0123456789ab", Method: "POST", Path: "/v1/upload?pane_id=w9%3Ap1",
			Host: "100.64.0.10:8787", TS: 1762689600, Nonce: "AAECAwQFBgcICQoLDA0ODw",
			Body: "--b\r\nContent-Disposition: form-data; name=\"file\"; filename=\"ä.txt\"\r\n\r\nhello whistle\n\r\n--b--\r\n",
		}
		f.BodySHA256, f.EmptyBodySHA256 = BodyHash([]byte(f.Body)), BodyHash(nil)
		f.Canonical = Canonical(f.Method, f.Path, f.Host, f.TS, f.Nonce, []byte(f.Body))
		f.Sig, _ = Sign(k, f.Canonical)
		f.Authorization = Header{Device: f.DeviceID, TS: f.TS, Nonce: f.Nonce, Sig: f.Sig}.String()
		f.Welcome = &struct {
			ServerID string `json:"server_id"`
			Nonce    string `json:"nonce"`
			Message  string `json:"message"`
			Sig      string `json:"sig"`
		}{ServerID: "4f1c2a9e8b7d6c5e4f3a2b1c0d9e8f7a", Nonce: f.Nonce}
		f.Welcome.Message = WelcomeMessage(f.Welcome.ServerID, f.Welcome.Nonce)
		f.Welcome.Sig, _ = Sign(k, f.Welcome.Message)
		// A terminal QR as the pair action prints it (first line: its URI),
		// decoded by the app's QR test (polarity: light modules printed).
		uri := PairURI("100.64.0.10:8787", "YYHQ7CZP3HHWAWWQO72E5EIULY", "MkR9tVZeCyn4s6dBt2aCjTQQfhPzyXnLrICFTJuIP-g")
		var q bytes.Buffer
		q.WriteString(uri + "\n")
		RenderQR(&q, uri)
		if err := os.WriteFile("testdata/pair_qr.txt", q.Bytes(), 0o644); err != nil {
			t.Fatal(err)
		}
		b, _ := json.MarshalIndent(f, "", "  ")
		if err := os.WriteFile("testdata/whistle_fixture_go.json", append(b, '\n'), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	checkFixture(t, readFixture(t, "whistle_fixture_go.json"))
}

func TestKotlinFixture(t *testing.T) {
	f := readFixture(t, "whistle_fixture_kotlin.json")
	if f.Welcome != nil {
		t.Fatal("the Kotlin fixture is a device request only")
	}
	checkFixture(t, f)
}

func TestCanonicalEmptyBody(t *testing.T) {
	got := Canonical("GET", "/v1/ws", "100.64.0.10:8787", 5, "n", nil)
	want := "whistle-v1\nGET\n/v1/ws\n100.64.0.10:8787\n5\nn\ne3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
	if got != want {
		t.Fatalf("%q", got)
	}
}

func TestParseHeaderRejects(t *testing.T) {
	for _, v := range []string{
		"", "Bearer x", "Whistle v3 device=a, ts=1, nonce=AAECAwQFBgcICQoLDA0ODw, sig=x",
		"Whistle v2 device=a, ts=1, nonce=AAECAwQFBgcICQoLDA0ODw, sig=x", // no challenge/body
		"Whistle v2 device=a, ts=1, nonce=AAECAwQFBgcICQoLDA0ODw, challenge=short, body=" + BodyHash(nil) + ", sig=x",
		"Whistle v2 device=a, ts=1, nonce=AAECAwQFBgcICQoLDA0ODw, challenge=AAECAwQFBgcICQoLDA0ODw, body=abc, sig=x",
		"Whistle v2 device=a, ts=1, nonce=AAECAwQFBgcICQoLDA0ODw, challenge=AAECAwQFBgcICQoLDA0ODw, body=" + strings.ToUpper(BodyHash(nil)) + ", sig=x",
		"Whistle v1 device=a, ts=1, nonce=AAECAwQFBgcICQoLDA0ODw, challenge=AAECAwQFBgcICQoLDA0ODw, sig=x",
		"Whistle v1 device=a, ts=x, nonce=AAECAwQFBgcICQoLDA0ODw, sig=x",
		"Whistle v1 device=a, ts=1, nonce=short, sig=x",
		"Whistle v1 device=a, ts=1, sig=x",
		"Whistle v1 device=a, device=b, ts=1, nonce=AAECAwQFBgcICQoLDA0ODw, sig=x",
		"Whistle v1 device=a, ts=1, nonce=AAECAwQFBgcICQoLDA0ODw, sig=x, extra=1",
	} {
		if _, err := ParseHeader(v); err == nil {
			t.Errorf("accepted %q", v)
		}
	}
}

func TestTokens(t *testing.T) {
	now := time.Unix(1000, 0)
	tk := NewTokens()
	tk.Now = func() time.Time { return now }
	tok, exp, err := tk.Issue()
	if err != nil || len(tok) != 26 || !exp.Equal(now.Add(TokenTTL)) {
		t.Fatal(tok, exp, err)
	}
	if !tk.Live(tok) {
		t.Fatal("not live")
	}
	if got, err := tk.Redeem(strings.ToLower(GroupCode(tok)), "ip1"); err != nil || got != tok {
		t.Fatal("grouped lower-case code:", got, err)
	}
	if _, err := tk.Redeem(tok, "ip1"); err != ErrPairingInvalid || tk.Live(tok) {
		t.Fatal("single use:", err)
	}
	tok, _, _ = tk.Issue()
	tk.Cancel(tok)
	if _, err := tk.Redeem(tok, "ip1"); err != ErrPairingInvalid {
		t.Fatal("cancelled:", err)
	}
	tok, _, _ = tk.Issue()
	now = now.Add(TokenTTL)
	if _, err := tk.Redeem(tok, "ip1"); err != ErrPairingInvalid {
		t.Fatal("expiry:", err)
	}
}

func TestTokensRateLimitPerSource(t *testing.T) {
	now := time.Unix(1000, 0)
	tk := NewTokens()
	tk.Now = func() time.Time { return now }
	tok, _, _ := tk.Issue()
	for i := 0; i < MaxFailures-2; i++ {
		tk.Redeem("AAAAAAAAAAAAAAAAAAAAAAAAAA", "evil")
	}
	tk.Redeem("AAAAAAAAAAAAAAAAAAAAAAAAAA", "evil")
	tk.Redeem("AAAAAAAAAAAAAAAAAAAAAAAAAA", "evil")
	if _, err := tk.Redeem("AAAAAAAAAAAAAAAAAAAAAAAAAA", "evil"); err != ErrRateLimited {
		t.Fatal("limited source:", err)
	}
	if _, err := tk.Redeem("AAAAAAAAAAAAAAAAAAAAAAAAAA", "phone"); err != ErrPairingInvalid {
		t.Fatal("other source must not be limited:", err)
	}
	if _, err := tk.Redeem(tok, "evil"); err != nil {
		t.Fatal("a matching token always succeeds:", err)
	}
	now = now.Add(FailureWindow)
	if _, err := tk.Redeem("AAAAAAAAAAAAAAAAAAAAAAAAAA", "evil"); err != ErrPairingInvalid {
		t.Fatal("window passed:", err)
	}
}

func TestChallenges(t *testing.T) {
	now := time.Unix(1000, 0)
	c := NewChallenges()
	c.Now = func() time.Time { return now }
	ch, exp, err := c.Issue("d1")
	if err != nil || !exp.Equal(now.Add(ChallengeTTL)) {
		t.Fatal(err)
	}
	if b, _ := b64u.DecodeString(ch); len(b) != ChallengeBytes {
		t.Fatal("size", ch)
	}
	if !c.Use("d1", ch) || c.Use("d1", ch) {
		t.Fatal("single use")
	}
	ch, _, _ = c.Issue("d1")
	if c.Use("d2", ch) || c.Use("d1", ch) {
		t.Fatal("bound to device (and burned when misused)")
	}
	ch, _, _ = c.Issue("d1")
	now = now.Add(ChallengeTTL)
	if c.Use("d1", ch) {
		t.Fatal("expired")
	}
}

func TestCanonicalV2AndHeader(t *testing.T) {
	got := CanonicalV2("GET", "/v1/ws", "h:1", 5, "n", BodyHash(nil), "c", "d1")
	want := "whistle-v2\nGET\n/v1/ws\nh:1\n5\nn\n" + BodyHash(nil) + "\nc\nd1"
	if got != want {
		t.Fatalf("%q", got)
	}
	h := Header{Version: 2, Device: "d1", TS: 5, Nonce: "AAECAwQFBgcICQoLDA0ODw", Challenge: "AAECAwQFBgcICQoLDA0ODw", Body: BodyHash(nil), Sig: "s"}
	p, err := ParseHeader(h.String())
	if err != nil || p != h {
		t.Fatalf("%+v %v", p, err)
	}
}

func TestKeyPermissionsRefused(t *testing.T) {
	p := filepath.Join(t.TempDir(), "bridge-key.pem")
	if _, err := LoadOrCreateKey(p); err != nil {
		t.Fatal(err)
	}
	os.Chmod(p, 0o640)
	if _, err := LoadOrCreateKey(p); err == nil || !strings.Contains(err.Error(), "private") {
		t.Fatal("group-readable key accepted:", err)
	}
}

func TestNonces(t *testing.T) {
	now := time.Unix(1000, 0)
	n := NewNonces()
	n.Now = func() time.Time { return now }
	if !n.Use("d", "x") || n.Use("d", "x") || !n.Use("e", "x") {
		t.Fatal("dedupe per device")
	}
	now = now.Add(NonceWindowSeconds*time.Second + time.Second)
	if !n.Use("d", "x") {
		t.Fatal("window expired")
	}
}

func TestIdentityKeyPersists(t *testing.T) {
	p := filepath.Join(t.TempDir(), "sub", "bridge-key.pem")
	k1, err := LoadOrCreateKey(p)
	if err != nil {
		t.Fatal(err)
	}
	st, _ := os.Stat(p)
	if st.Mode().Perm() != 0o600 {
		t.Fatalf("mode %v", st.Mode())
	}
	k2, err := LoadOrCreateKey(p)
	if err != nil || !k1.Equal(k2) {
		t.Fatal("key not reloaded", err)
	}
}

func TestPairURIAndQR(t *testing.T) {
	u := PairURI("100.64.0.10:8787", "ABCDEFGHIJKLMNOPQRSTUVWXYZ", "fp_-")
	want := "whistle://pair?v=1&u=100.64.0.10:8787&t=ABCDEFGHIJKLMNOPQRSTUVWXYZ&f=fp_-"
	if u != want {
		t.Fatalf("%s", u)
	}
	var b bytes.Buffer
	if err := RenderQR(&b, u); err != nil {
		t.Fatal(err)
	}
	lines := strings.Split(strings.TrimRight(b.String(), "\n"), "\n")
	if len(lines) < 15 || !strings.HasPrefix(lines[0], "████") {
		t.Fatalf("qr:\n%s", b.String())
	}
	if NormalizeCode(GroupCode("ABCDEFGHIJKLMNOPQRSTUVWXYZ")) != "ABCDEFGHIJKLMNOPQRSTUVWXYZ" {
		t.Fatal("code round trip")
	}
}

var updateV2 = flag.Bool("update-v2", false, "rewrite testdata/whistle_fixture_go_v2.json")

// fixtureV2 is the v2 (server challenge) signed-request fixture for the app.
type fixtureV2 struct {
	Comment       string `json:"comment"`
	PublicKey     string `json:"public_key"`
	DeviceID      string `json:"device_id"`
	Method        string `json:"method"`
	Path          string `json:"path"`
	Host          string `json:"host"`
	TS            int64  `json:"ts"`
	Nonce         string `json:"nonce"`
	Challenge     string `json:"challenge"`
	Body          string `json:"body"`
	BodySHA256    string `json:"body_sha256"`
	Canonical     string `json:"canonical"`
	Sig           string `json:"sig"`
	Authorization string `json:"authorization"`
}

func TestGoFixtureV2(t *testing.T) {
	path := filepath.Join("testdata", "whistle_fixture_go_v2.json")
	if *updateV2 {
		k, _ := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
		f := fixtureV2{
			Comment:   "Generated by bridge/internal/devauth (go test -run TestGoFixtureV2 -update-v2). Whistle v2 auth (server challenge from GET /v1/challenge).",
			PublicKey: base64.StdEncoding.EncodeToString(SPKI(&k.PublicKey)),
			DeviceID:  "d0123456789ab", Method: "POST", Path: "/v1/upload?pane_id=w9%3Ap1",
			Host: "100.64.0.10:8787", TS: 1762689600, Nonce: "AAECAwQFBgcICQoLDA0ODw",
			Challenge: "EBESExQVFhcYGRobHB0eHw",
			Body:      "--b\r\nContent-Disposition: form-data; name=\"file\"; filename=\"ä.txt\"\r\n\r\nhello whistle\n\r\n--b--\r\n",
		}
		f.BodySHA256 = BodyHash([]byte(f.Body))
		f.Canonical = CanonicalV2(f.Method, f.Path, f.Host, f.TS, f.Nonce, f.BodySHA256, f.Challenge, f.DeviceID)
		f.Sig, _ = Sign(k, f.Canonical)
		f.Authorization = Header{Version: 2, Device: f.DeviceID, TS: f.TS, Nonce: f.Nonce, Challenge: f.Challenge, Body: f.BodySHA256, Sig: f.Sig}.String()
		b, _ := json.MarshalIndent(f, "", "  ")
		if err := os.WriteFile(path, append(b, '\n'), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var f fixtureV2
	if err := json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	pub, err := ParsePublicKey(f.PublicKey)
	if err != nil {
		t.Fatal(err)
	}
	if BodyHash([]byte(f.Body)) != f.BodySHA256 ||
		CanonicalV2(f.Method, f.Path, f.Host, f.TS, f.Nonce, f.BodySHA256, f.Challenge, f.DeviceID) != f.Canonical {
		t.Fatal("canonical mismatch")
	}
	if !Verify(pub, f.Canonical, f.Sig) {
		t.Fatal("signature does not verify")
	}
	h, err := ParseHeader(f.Authorization)
	if err != nil || h.Version != 2 || h.Challenge != f.Challenge || h.Body != f.BodySHA256 || h.Sig != f.Sig {
		t.Fatalf("header %+v %v", h, err)
	}
}
